@st.composite
def mesh_node_strategy(draw):
    """Generate valid MeshNode instances."""
    return MeshNode(
        node_id=draw(st.integers(min_value=0, max_value=2**32 - 1)),
        address=draw(st.ip_addresses().map(str)),
        port=draw(st.integers(min_value=1, max_value=65535)),
    )


@st.composite
def mesh_link_strategy(draw):
    """Generate valid MeshLink instances."""
    return MeshLink(
        node_a=draw(st.integers(min_value=0, max_value=2**32 - 1)),
        node_b=draw(st.integers(min_value=0, max_value=2**32 - 1)),
    )


@st.composite
def mesh_topology_strategy(draw):
    """Generate valid MeshTopology instances with consistent node/link references."""
    node_count = draw(st.integers(min_value=2, max_value=20))
    nodes = tuple(
        MeshNode(
            node_id=i,
            address=draw(st.ip_addresses().map(str)),
            port=draw(st.integers(min_value=1, max_value=65535)),
        )
        for i in range(node_count)
    )
    
    # Generate links ensuring node references are valid
    link_count = draw(st.integers(min_value=1, max_value=node_count * 2))
    links = []
    for _ in range(link_count):
        node_a = draw(st.integers(min_value=0, max_value=node_count - 1))
        node_b = draw(st.integers(min_value=0, max_value=node_count - 1))
        if node_a != node_b:  # No self-links
            links.append(MeshLink(node_a=node_a, node_b=node_b))
    
    return MeshTopology(nodes=nodes, links=tuple(links))


