class MeshTopologyStateMachine(RuleBasedStateMachine):
    """Stateful testing of MeshTopology operations."""

    def __init__(self):
        super().__init__()
        self.topology = MeshTopology(
            nodes=(
                MeshNode(node_id=1, address="10.0.0.1", port=10001),
                MeshNode(node_id=2, address="10.0.0.2", port=10002),
            ),
            links=(MeshLink(node_a=1, node_b=2),)
        )
        self.node_counter = 3

    @rule()
    def add_node(self):
        """Add a new node to the topology."""
        node = MeshNode(
            node_id=self.node_counter,
            address=f"10.0.0.{self.node_counter}",
            port=10000 + self.node_counter
        )
        self.topology.add_node(node)
        self.node_counter += 1

    @rule()
    @precondition(lambda self: self.topology.node_count > 2)
    def remove_random_node(self):
        """Remove a random node from the topology."""
        node_ids = [node.node_id for node in self.topology.nodes]
        import random
        node_id = random.choice(node_ids)
        self.topology.remove_node(node_id)

    @rule()
    @precondition(lambda self: self.topology.node_count >= 2)
    def add_link(self):
        """Add a link between two random nodes."""
        node_ids = [node.node_id for node in self.topology.nodes]
        import random
        node_a, node_b = random.sample(node_ids, 2)
        self.topology.add_link(MeshLink(node_a=node_a, node_b=node_b))

    @invariant()
    def node_count_non_negative(self):
        """Node count must never be negative."""
        assert self.topology.node_count >= 0

    @invariant()
    def link_count_non_negative(self):
        """Link count must never be negative."""
        assert self.topology.link_count >= 0

    @invariant()
    def all_links_reference_valid_nodes(self):
        """All links must reference existing nodes."""
        node_ids = {node.node_id for node in self.topology.nodes}
        for link in self.topology.links:
            assert link.node_a in node_ids
            assert link.node_b in node_ids

    @invariant()
    def no_self_links(self):
        """No self-links allowed."""
        for link in self.topology.links:
            assert link.node_a != link.node_b


TestMeshTopologyStateful = MeshTopologyStateMachine.TestCase


