class TestEdgeCases:
    """Edge cases and failure modes."""

    def test_node_with_max_port(self):
        """Test node with maximum valid port."""
        node = MeshNode(node_id=1, address="10.0.0.1", port=65535)
        assert node.port == 65535

    def test_node_with_min_port(self):
        """Test node with minimum valid port."""
        node = MeshNode(node_id=1, address="10.0.0.1", port=1)
        assert node.port == 1

    def test_link_with_large_node_ids(self):
        """Test link with large node IDs."""
        link = MeshLink(node_a=2**32 - 1, node_b=2**32 - 2)
        assert link.node_a == 2**32 - 1

    def test_topology_with_single_node(self):
        """Test topology with single node (no links)."""
        node = MeshNode(node_id=1, address="10.0.0.1", port=10001)
        topology = MeshTopology(nodes=(node,), links=())
        assert topology.node_count == 1
        assert topology.link_count == 0
        assert topology.is_connected()  # Single node is trivially connected

    def test_topology_with_max_links(self):
        """Test complete graph topology."""
        size = 10
        nodes = tuple(
            MeshNode(node_id=i, address=f"10.0.0.{i}", port=10000 + i)
            for i in range(size)
        )
        links = tuple(
            MeshLink(node_a=i, node_b=j)
            for i in range(size)
            for j in range(i + 1, size)
        )
        
        topology = MeshTopology(nodes=nodes, links=links)
        assert topology.link_count == size * (size - 1) // 2  # Complete graph

    def test_invalid_topology_type_raises(self):
        """Test that wrong types raise TypeError."""
        with pytest.raises(TypeError):
            MeshTopology(nodes="not-a-tuple", links=())

    def test_invalid_link_type_raises(self):
        """Test that invalid link type raises TypeError."""
        node = MeshNode(node_id=1, address="10.0.0.1", port=10001)
        with pytest.raises(TypeError):
            MeshTopology(nodes=(node,), links=("not-a-link",))

    def test_mutation_immutability(self):
        """Test that topology is immutable after construction."""
        node_a = MeshNode(node_id=1, address="10.0.0.1", port=10001)
        node_b = MeshNode(node_id=2, address="10.0.0.2", port=10002)
        topology = MeshTopology(
            nodes=(node_a, node_b),
            links=(MeshLink(node_a=1, node_b=2),)
        )
        
        with pytest.raises((AttributeError, TypeError)):
            topology.nodes = ()  # Attempt to mutate

    def test_node_immutability(self):
        """Test that node fields are immutable."""
        node = MeshNode(node_id=1, address="10.0.0.1", port=10001)
        
        with pytest.raises((AttributeError, TypeError)):
            node.port = 9999  # Attempt to mutate

    def test_link_immutability(self):
        """Test that link fields are immutable."""
        link = MeshLink(node_a=1, node_b=2)
        
        with pytest.raises((AttributeError, TypeError)):
            link.node_a = 3  # Attempt to mutate


